    /** [c] as the firmware draws it: lowercase as capitals, an unknown code as '?'. */
    fun of(c: Int): IntArray {
        var k = c
        if (k in 'a'.code..'z'.code) k -= 32
        if (k >= 0xE0) k -= 0x20
        return glyphs[k] ?: glyphs['?'.code]!!
    }
